import {SceneView} from './scene.js';
import {colorSlots,CATEGORY_KINDS} from './asset-schema.js';
const $=id=>document.getElementById(id);
const thumbnails=new Map();let thumbnailStarted=false;const thumbAbort=new AbortController();
function showThumb(kind,url){thumbnails.set(kind,url);const b=document.querySelector('[data-asset="'+kind+'"]');if(b){const icon=b.querySelector('.asset-icon');if(icon){const img=document.createElement('img');img.src=url;img.alt='';img.className='asset-preview';icon.replaceWith(img);}}}
function startThumbnails(){if(thumbnailStarted)return;thumbnailStarted=true;import('./thumbnails.js').then(m=>m.buildThumbnails(showThumb,thumbAbort.signal)).catch(()=>{});}
const store=new SceneStore(initialScene());let storage;try{storage=localStorage;}catch{storage=null;}
const hub=new MockHub({storage}),services=new MockServices(),presence=new PresenceAdapter();
let profile='desktop',revision=0,selected=null,busy=false,dirty=false,view,toastTimer,editing=false,activeTab='light',assetMode='orbit',snapshot=null,online=true,commandPending=false,reading=false;
const grid=new DashboardView($('widget-grid'),{change:dashboard=>change(s=>s.dashboard=dashboard),command:sendCommand,detail:showDetail,notify:toast});
function toast(message){$('toast').textContent=message;$('toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').hidden=true,5000);}
function status(message){$('hub-status').textContent=message||`${dirty?'Unsaved changes':'Saved locally'} · rev ${revision}`;}
function setBusy(value){busy=value;document.querySelector('.workspace').inert=value;$('save').disabled=value;}
function tab(name){activeTab=name;for(const key of ['light','object','widget']){$('tab-'+key).setAttribute('aria-selected',String(key===name));$(key+'-panel').hidden=key!==name;}updateMode();}
function updateMode(){const assets=editing&&activeTab==='object';$('ecosystem').classList.toggle('editing-assets',assets);document.querySelector('.scene-controls').hidden=!assets;$('asset-section').hidden=!editing;if(editing)startThumbnails();$('customize').textContent=editing?'Done editing':'Customize';$('customize').setAttribute('aria-pressed',String(editing));grid.setLayout(store.scene.dashboard,editing&&!assets);view?.setMode(assets?assetMode:'fixed');view?.highlight(assets?selected:null);for(const mode of ['orbit','move']){$(mode).classList.toggle('active',assetMode===mode);$(mode).setAttribute('aria-pressed',String(assetMode===mode));}if(!assets)view?.resetCamera();$('interaction-hint').textContent=assets?'Select an asset · Orbit or drag with Move objects':editing?'Drag widget headers · Resize corners · Arrow keys move; Shift + arrows resize':'Home data is simulated · Customize to arrange your space';}
function select(id){selected=id;view?.highlight(id);renderList();renderObject();if(id){editing=true;tab('object');}}
function change(fn){if(busy)return;try{const before=store.scene;store.edit(s=>{fn(s);stashCustomScene(s);});if(before!==store.scene)dirty=true;render();status();}catch(error){toast(error.message);render();}}
function objectEdit(fn){if(selected)change(s=>{const e=s.elements.find(x=>x.id===selected);if(e)fn(e);});}
function renderList(){$('elements').replaceChildren();for(const e of store.scene.elements){const b=document.createElement('button');b.className='element-row'+(e.id===selected?' active':'');b.setAttribute('aria-pressed',String(e.id===selected));const icon=document.createElement('span');icon.className='element-icon';icon.textContent=ASSETS[e.kind].icon;const name=document.createElement('span');name.textContent=e.name;b.append(icon,name);b.onclick=()=>select(e.id);$('elements').append(b);}$('element-count').textContent=store.scene.elements.length;$('objects').textContent=store.scene.elements.length;}
function renderObject(){const e=store.scene.elements.find(x=>x.id===selected);$('empty-selection').hidden=!!e;$('object-fields').hidden=!e;if(!e)return;$('asset-seed').value=e.seed;$('variation').value=e.variation;$('variation-value').value=Math.round(e.variation*100)+'%';renderAssetColors(e);$('object-name').value=e.name;['x','y','z'].forEach((axis,i)=>$('pos-'+axis).value=e.position[i].toFixed(2));$('object-color').value=e.color;$('object-color').parentElement.hidden=true;for(const key of ['scale','roughness','transmission','absorption']){$(key).value=e[key];$(key+'-value').value=e[key].toFixed(2);}$('rotation').value=e.rotation*180/Math.PI;$('rotation-value').value=Math.round(e.rotation*180/Math.PI)+'°';$('material-fields').hidden=!['crystal','quartz','geode','obelisk','fluorite','aragonite'].includes(e.kind);}
function render(){const s=store.scene,t=sceneTheme(s);document.documentElement.style.setProperty('--accent',t.accent);$('scene-title').textContent=t.name;renderCustomScenes();$('widget-opacity').value=Math.round(s.dashboard.opacity*100);$('widget-opacity-value').value=Math.round(s.dashboard.opacity*100)+'%';$('widget-gap').value=s.dashboard.gap;$('widget-gap-value').value=s.dashboard.gap+'px';$('world-caption').textContent=t.caption.toUpperCase();$('biome-code').textContent=String(Object.keys(THEMES).indexOf(s.theme)+1).padStart(2,'0');document.querySelectorAll('[data-theme]').forEach(b=>{b.classList.toggle('active',!s.custom&&b.dataset.theme===s.theme);b.setAttribute('aria-pressed',String(b.dataset.theme===s.theme));});$('light-color').value=s.lighting.color;$('clock-material').value=s.dashboard.clockMaterial;$('single-source').checked=s.lighting.singleSource;['x','y','z'].forEach((axis,i)=>$('light-'+axis).value=s.lighting.position[i]);for(const key of ['speed','waves','direction']){$('water-'+key).value=s.water[key];$('water-'+key+'-value').value=s.water[key];}for(const key of ['intensity','bloom','exposure','ambient']){$(key).value=s.lighting[key];$(key+'-value').value=s.lighting[key].toFixed(key==='intensity'?0:2);}$('undo').disabled=!store.past.length;$('redo').disabled=!store.future.length;if(!s.elements.some(e=>e.id===selected))selected=null;renderList();renderObject();view?.update(s);view?.highlight(editing&&activeTab==='object'?selected:null);grid.setLayout(s.dashboard,editing&&activeTab!=='object');renderWidgetSettings();}
for(const [id,t] of Object.entries(THEMES)){const b=document.createElement('button');b.className='theme-button';b.dataset.theme=id;const chip=document.createElement('span');chip.className='theme-chip';chip.style.background=`linear-gradient(145deg,${t.crystal},${t.water} 55%,${t.background})`;const words=document.createElement('span');const strong=document.createElement('strong');strong.textContent=t.name;const small=document.createElement('small');small.textContent=t.caption;words.append(strong,small);b.append(chip,words);b.onclick=()=>{selected=null;change(s=>{const next=initialScene(id);s.custom=null;s.theme=id;s.lighting=next.lighting;s.elements=next.elements;});view?.resetCamera();};$('themes').append(b);}
function renderLibrary(){const category=$('asset-category').value;$('library').replaceChildren();for(const [folder,kinds] of Object.entries(CATEGORY_KINDS)){if(category!=='All assets'&&folder!==category)continue;const details=document.createElement('details');details.className='asset-folder';details.open=category!=='All assets'||folder==='Crystals';const heading=document.createElement('summary');heading.textContent=folder+' · '+kinds.length+' assets';const content=document.createElement('div');content.className='library-grid';details.append(heading,content);$('library').append(details);for(const kind of kinds){const b=document.createElement('button');b.className='asset';b.dataset.asset=kind;b.setAttribute('aria-label','Add '+ASSETS[kind].name);b.innerHTML=`<span class="asset-add">+</span><span class="asset-icon" aria-hidden="true">${ASSETS[kind].icon}</span><span class="asset-name">${ASSETS[kind].name}</span>`;b.onclick=()=>{if(store.scene.elements.length>=40){toast('Maximum 40 assets per ecosystem.');return;}const e=element(kind);if(ASSETS[kind].group==='Crystals')e.color=sceneTheme(store.scene).crystal;if(kind==='water')e.colors.body=sceneTheme(store.scene).water;e.position=kind==='clock'?[0,2.8,-2.6]:[Math.sin(store.scene.elements.length)*3,0,Math.cos(store.scene.elements.length)*3];change(s=>s.elements.push(e));select(e.id);};content.append(b);if(thumbnails.has(kind))showThumb(kind,thumbnails.get(kind));}}}
$('asset-category').onchange=renderLibrary;renderLibrary();
for(const color of ['#bca5ff','#63d9ee','#d6e7a5','#ffc178','#ff87a7','#ffffff']){const b=document.createElement('button');b.className='swatch';b.style.background=color;b.setAttribute('aria-label','Light color '+color);b.onclick=()=>change(s=>s.lighting.color=color);$('swatches').append(b);}
for(const key of ['intensity','bloom','exposure','ambient']){$(key).oninput=()=>$(key+'-value').value=Number($(key).value).toFixed(key==='intensity'?0:2);$(key).onchange=()=>change(s=>s.lighting[key]=Number($(key).value));}
$('single-source').onchange=e=>change(s=>s.lighting.singleSource=e.target.checked);['x','y','z'].forEach((axis,i)=>$('light-'+axis).onchange=e=>change(s=>s.lighting.position[i]=Number(e.target.value)));for(const key of ['speed','waves','direction']){$('water-'+key).oninput=e=>$('water-'+key+'-value').value=e.target.value;$('water-'+key).onchange=e=>change(s=>s.water[key]=Number(e.target.value));}
$('light-color').onchange=e=>change(s=>s.lighting.color=e.target.value);$('clock-material').onchange=e=>change(s=>s.dashboard.clockMaterial=e.target.value);
for(const key of ['scale','roughness','transmission','absorption']){$(key).oninput=()=>$(key+'-value').value=Number($(key).value).toFixed(2);$(key).onchange=()=>objectEdit(e=>e[key]=Number($(key).value));}
$('rotation').oninput=()=>$('rotation-value').value=$('rotation').value+'°';$('rotation').onchange=()=>objectEdit(e=>e.rotation=Number($('rotation').value)*Math.PI/180);
$('object-name').onchange=()=>objectEdit(e=>e.name=$('object-name').value.trim());$('object-color').onchange=()=>objectEdit(e=>e.color=$('object-color').value);
['x','y','z'].forEach((axis,i)=>$('pos-'+axis).onchange=()=>objectEdit(e=>e.position[i]=Number($('pos-'+axis).value)));
$('duplicate').onclick=()=>{if(store.scene.elements.length>=40){toast('Maximum 40 assets.');return;}const e=clone(store.scene.elements.find(x=>x.id===selected));if(!e)return;e.id=crypto.randomUUID();e.name=(e.name+' copy').slice(0,60);e.position[0]=Math.min(10,e.position[0]+.5);change(s=>s.elements.push(e));select(e.id);};$('delete').onclick=()=>change(s=>s.elements=s.elements.filter(e=>e.id!==selected));
function undo(){if(store.undo()){dirty=true;render();status();}}function redo(){if(store.redo()){dirty=true;render();status();}}$('undo').onclick=undo;$('redo').onclick=redo;
window.addEventListener('keydown',e=>{if(['INPUT','TEXTAREA','SELECT'].includes(e.target.tagName))return;if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='z'){e.preventDefault();e.shiftKey?redo():undo();}if(e.key==='Escape'&&!$('detail-dialog').open&&!$('scene-dialog').open){selected=null;view?.highlight(null);}});
for(const key of ['light','object','widget'])$('tab-'+key).onclick=()=>tab(key);
document.querySelector('.tabs').onkeydown=e=>{if(['ArrowLeft','ArrowRight'].includes(e.key)){e.preventDefault();const keys=['light','object','widget'];tab(keys[(keys.indexOf(activeTab)+(e.key==='ArrowRight'?1:2))%3]);$('tab-'+activeTab).focus();}};
$('customize').onclick=()=>{editing=!editing;updateMode();};$('add-focus').onclick=()=>{editing=true;tab('object');$('asset-section').scrollIntoView({behavior:'smooth',block:'start'});$('library').querySelector('details').open=true;$('library').querySelector('button')?.focus();};
$('orbit').onclick=()=>{assetMode='orbit';view?.setMode(assetMode);$('orbit').classList.add('active');$('move').classList.remove('active');updateMode();};$('move').onclick=()=>{assetMode='move';view?.setMode(assetMode);$('move').classList.add('active');$('orbit').classList.remove('active');updateMode();};$('reset-camera').onclick=()=>view?.resetCamera();
$('pause').onclick=()=>{if(view){view.paused=!view.paused;$('pause').textContent=view.paused?'Resume':'Pause';$('pause').setAttribute('aria-pressed',String(view.paused));}};
$('home-mode').onclick=()=>{document.body.classList.toggle('focus-view');$('home-mode').textContent=document.body.classList.contains('focus-view')?'Show settings':'Focus view';};
for(const [type,w] of Object.entries(WIDGETS)){const o=document.createElement('option');o.value=type;o.textContent=w.name;$('widget-type').append(o);}
$('add-widget').onclick=()=>{try{const next=addWidget(store.scene.dashboard,$('widget-type').value);change(s=>s.dashboard=next);editing=true;updateMode();}catch(e){toast(e.message);}};
function renderWidgetSettings(){$('widget-settings').replaceChildren();for(const w of store.scene.dashboard.widgets){const row=document.createElement('div');row.className='widget-setting';const name=document.createElement('span');name.textContent=WIDGETS[w.type].name+' · '+w.w+'×'+w.h;const remove=document.createElement('button');remove.textContent='×';remove.setAttribute('aria-label','Remove '+WIDGETS[w.type].name);remove.onclick=()=>change(s=>s.dashboard.widgets=s.dashboard.widgets.filter(x=>x.id!==w.id));row.append(name,remove);$('widget-settings').append(row);}}
async function pull(next=profile){if(busy)return;if(dirty&&!confirm('Pull this profile and discard unsaved changes?')){$('profile').value=profile;return;}setBusy(true);status('Pulling profile…');try{const result=await hub.pull(next);profile=next;revision=result.revision;store.replace(result.scene);dirty=false;selected=null;view?.quality(profile);$('quality-label').textContent=profile.toUpperCase();render();status();if(!storage)status('Memory only · storage unavailable');}catch(e){toast(e.message);status('Pull failed · changes retained');}finally{$('profile').value=profile;setBusy(false);}}
$('profile').onchange=e=>pull(e.target.value);$('pull').onclick=()=>pull();$('save').onclick=async()=>{if(busy)return;setBusy(true);status('Saving space…');try{const result=await hub.save(profile,store.scene,revision);revision=result.revision;dirty=false;status();toast(storage?'Ecosystem and widget layout saved locally.':'Saved for this session.');}catch(e){status(e.name==='ConflictError'?'Conflict · pull newer revision':'Save failed · changes retained');toast(e.message);}finally{setBusy(false);}};
$('offline').onchange=e=>{hub.offline=services.offline=e.target.checked;online=!services.offline;grid.setData(snapshot,online,commandPending);refreshServices();status(hub.offline?'Demo hub offline':undefined);};
$('export').onclick=()=>{const blob=new Blob([JSON.stringify({profile,revision,scene:store.scene},null,2)],{type:'application/json'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`lumen-${profile}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
function updatePresence(){if($('presence').checked)presence.receive({source:'simulation',timestamp:Date.now(),confidence:1,position:[Number($('visitor').value),1,2]});else presence.clear();view?.presence(presence.sample());$('visitor-value').value=Number($('visitor').value).toFixed(1);$('presence-status').textContent=$('presence').checked?'Presence simulation active':'No sensors connected';}
$('presence').onchange=()=>{$('visitor').disabled=!$('presence').checked;updatePresence();};$('visitor').oninput=updatePresence;
function acceptSnapshot(next){if(!snapshot||next.sequence>=snapshot.sequence)snapshot=next;grid.setData(snapshot,online,commandPending);renderServiceStatus();}
async function refreshServices(){if(reading||document.hidden)return;reading=true;try{const next=await services.read();online=true;acceptSnapshot(next);}catch{online=false;grid.setData(snapshot,false,commandPending);renderServiceStatus();}finally{reading=false;}}
async function sendCommand(action,value){if(commandPending||!online||!snapshot||freshness(snapshot)==='stale'){toast('Wait for a fresh hub connection before sending commands.');return;}commandPending=true;grid.setData(snapshot,online,true);try{acceptSnapshot(await services.command({id:crypto.randomUUID(),action,...(value===undefined?{}:{value})}));toast('Demo hub acknowledged the command.');}catch(e){toast(e.message);}finally{commandPending=false;grid.setData(snapshot,online,false);}}
function renderServiceStatus(){const stale=!snapshot||freshness(snapshot)==='stale';$('connection').textContent=!online?'DEMO · OFFLINE':stale?'DEMO · WAITING':'DEMO · CONNECTED';$('service-list').replaceChildren();for(const [id,name] of [['home','Home devices'],['weather','Weather service'],['camera','Camera gateway'],['media','Media service']]){const row=document.createElement('div');row.className='service-row';const label=document.createElement('span');label.textContent=name;const state=document.createElement('span');state.textContent=!online?'Offline':snapshot?.sources[id]==='online'?'Demo ready':'Unavailable';if(!online||snapshot?.sources[id]!=='online')state.className='bad';row.append(label,state);$('service-list').append(row);}$('data-age').textContent=snapshot?`Last telemetry ${Math.max(0,Math.floor((Date.now()-snapshot.timestamp)/1000))}s ago${stale?' · stale':''}`:'Waiting for telemetry…';}
function showDetail(type){if(!snapshot){toast('Waiting for telemetry.');return;}$('detail-title').textContent=WIDGETS[type].name;$('detail-body').replaceChildren();const values=snapshot[WIDGETS[type].source];for(const [key,value] of Object.entries(values)){if(key==='history'||key==='url')continue;const row=document.createElement('div');row.className='detail-row';const label=document.createElement('span');label.textContent=key.replace(/([A-Z])/g,' $1');const val=document.createElement('strong');val.textContent=String(value);row.append(label,val);$('detail-body').append(row);}const note=document.createElement('p');note.className='detail-note';note.textContent='Demonstration data supplied by the mock central hub. No private devices, camera or Spotify account are connected.';$('detail-body').append(note);if(type==='home'){const button=document.createElement('button');button.className='wide';button.textContent=snapshot.home.lightsOn?'Turn demo lights off':'Turn demo lights on';button.disabled=!online||commandPending||freshness(snapshot)==='stale';button.onclick=async()=>{button.disabled=true;await sendCommand('home.lights',!snapshot.home.lightsOn);$('detail-dialog').close();};$('detail-body').append(button);}$('detail-dialog').showModal();}
$('close-detail').onclick=()=>$('detail-dialog').close();$('detail-dialog').onclick=e=>{if(e.target===$('detail-dialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close();}};
function graphicsError(message){$('graphics-error').hidden=false;$('graphics-error').textContent=message;}$('viewport').addEventListener('scene-error',e=>graphicsError(e.detail));
try{view=new SceneView($('viewport'),{select,move:(id,position)=>change(s=>{s.elements.find(e=>e.id===id).position=position;}),stats:fps=>$('fps').textContent=fps});view.quality(profile);view.setMode('fixed');$('pause').textContent=view.paused?'Resume':'Pause';$('pause').setAttribute('aria-pressed',String(view.paused));}catch(e){console.error(e);graphicsError('WebGL2 unavailable. The home dashboard and configuration still work.');}
function tick(){updatePresence();renderServiceStatus();$('date-label').textContent=new Date().toLocaleDateString([],{weekday:'long',month:'long',day:'numeric'});}
const telemetryTimer=setInterval(refreshServices,5000),clockTimer=setInterval(tick,1000);document.addEventListener('visibilitychange',()=>{if(!document.hidden)refreshServices();});
window.addEventListener('beforeunload',e=>{if(dirty){e.preventDefault();e.returnValue='';}});window.addEventListener('pagehide',()=>{clearInterval(telemetryTimer);clearInterval(clockTimer);thumbAbort.abort();grid.dispose();view?.dispose();});


function renderAssetColors(e){
  $('asset-colors').replaceChildren();const specs={...colorSlots(e.kind)};
  if(['clock','light','portal'].includes(e.kind)||ASSETS[e.kind].group==='Crystals')specs.tint={label:'Tint / glow'};
  for(const [key,spec] of Object.entries(specs)){const label=document.createElement('label');label.textContent=spec.label;const input=document.createElement('input');input.type='color';input.value=key==='tint'?e.color:e.colors[key];input.dataset.colorSlot=key;input.onchange=()=>objectEdit(asset=>{if(key==='tint')asset.color=input.value;else asset.colors[key]=input.value;});label.append(input);$('asset-colors').append(label);}
}
$('asset-seed').onchange=e=>objectEdit(asset=>asset.seed=Number(e.target.value));
$('reroll').onclick=()=>objectEdit(asset=>asset.seed=crypto.getRandomValues(new Uint32Array(1))[0]);
$('variation').oninput=e=>$('variation-value').value=Math.round(Number(e.target.value)*100)+'%';
$('variation').onchange=e=>objectEdit(asset=>asset.variation=Number(e.target.value));
for(const key of ['opacity','gap']){
  const input=$('widget-'+key);input.oninput=()=>{const value=Number(input.value);$('widget-'+key+'-value').value=value+(key==='opacity'?'%':'px');grid.root.style.setProperty(key==='opacity'?'--widget-opacity':'--widget-gap',key==='opacity'?value/100:value+'px');};
  input.onchange=()=>change(s=>s.dashboard[key]=Number(input.value)/(key==='opacity'?100:1));
}
function renderCustomScenes(){
  const s=store.scene;$('custom-scenes').replaceChildren();for(const saved of s.library){const b=document.createElement('button');b.className='custom-scene-button';b.textContent=saved.custom.name;b.setAttribute('aria-pressed',String(saved.custom.id===s.custom?.id));b.onclick=()=>{selected=null;change(next=>Object.assign(next,openCustomScene(next,saved.custom.id)));view?.resetCamera();};const remove=document.createElement('button');remove.textContent='×';remove.setAttribute('aria-label','Remove scene '+saved.custom.name);remove.onclick=()=>change(next=>{next.library=next.library.filter(entry=>entry.custom.id!==saved.custom.id);if(next.custom?.id===saved.custom.id)next.custom=null;});const row=document.createElement('div');row.className='button-row';row.append(b,remove);$('custom-scenes').append(row);}
  $('custom-scene-settings').hidden=!s.custom;if(!s.custom)return;$('custom-name').value=s.custom.name;$('scene-palette').replaceChildren();
  for(const key of ['background','ground','water','accent','crystal','fill']){const label=document.createElement('label');label.textContent=key;const input=document.createElement('input');input.type='color';input.value=s.custom.palette[key];input.onchange=()=>change(next=>{next.custom.palette[key]=input.value;if(key==='water')for(const e of next.elements)if(e.kind==='water')e.colors.body=input.value;if(key==='crystal')for(const e of next.elements)if(ASSETS[e.kind].group==='Crystals')e.color=input.value;});label.append(input);$('scene-palette').append(label);}
}
$('new-scene').onclick=()=>{$('new-scene-name').value='';$('scene-form-error').textContent='';$('scene-dialog').showModal();$('new-scene-name').focus();};
$('cancel-scene').onclick=()=>$('scene-dialog').close();
$('custom-name').onchange=e=>change(s=>s.custom.name=e.target.value);
$('scene-form').onsubmit=e=>{e.preventDefault();try{const scene=createCustomScene(store.scene,$('new-scene-name').value,$('new-scene-base').value);selected=null;change(s=>Object.assign(s,scene));$('scene-dialog').close();editing=true;tab('object');view?.resetCamera();}catch(error){$('scene-form-error').textContent=error.message;}};

render();updateMode();pull();refreshServices();tick();

